import { useMemo } from 'react';
import { useLocation, useParams, matchPath } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import type { BreadcrumbItem } from '@/components/layout/Breadcrumbs';
import { ROUTE_META, type RouteMeta } from '@/lib/routeMeta';

/**
 * Build breadcrumb items from the current route by matching the URL against
 * the declarative `ROUTE_META` map (which is itself derived from the
 * autogenerated `ROUTE_REGISTRY`). Every registered frontend route therefore
 * gets a baseline breadcrumb entry; pages that opt into a parent chain
 * surface it via `PARENT_OVERRIDES` in `lib/routeMeta.ts`.
 *
 * Pages may supply per-render label overrides (e.g. `"Drive #4421"` →
 * `"Trip to office"` once the entity is loaded) via the `overrides` map,
 * keyed by the route pattern (`/drives/:id`). The recommended way to feed
 * overrides is the `breadcrumbLabels` prop on `<PageContainer>`, which
 * passes them straight through to this hook.
 *
 * Returns an empty array only for unknown / chrome-less routes. Registered
 * top-level routes return one current-page item so the global Layout can
 * render Home > Current Page everywhere without per-page wiring.
 */
export function useBreadcrumbs(overrides?: Partial<Record<string, string>>): BreadcrumbItem[] {
  const location = useLocation();
  const params = useParams();
  const { t } = useTranslation();

  return useMemo(() => {
    const path = location.pathname;

    // Find which route pattern matches the current path. Iterate registered
    // patterns and pick the first exact match.
    let matchedPattern: string | undefined;
    for (const pattern of Object.keys(ROUTE_META)) {
      if (matchPath({ path: pattern, end: true }, path)) {
        matchedPattern = pattern;
        break;
      }
    }
    if (!matchedPattern) return [];

    const items: BreadcrumbItem[] = [];
    const visited = new Set<string>();
    let current: string | undefined = matchedPattern;

    while (current) {
      // Defensive: cycle break (the routeMeta unit test also enforces this).
      if (visited.has(current)) break;
      visited.add(current);

      const meta: RouteMeta | undefined = ROUTE_META[current];
      if (!meta) break;

      // Resolve label: page-supplied override > i18n key > default label.
      // The i18n key falls back to `defaultLabel`, so missing translations
      // still render sensibly. Cast `t()` because i18next's overloaded return
      // type is `string | object` and we always pass a string fallback.
      const override = overrides?.[current];
      let label: string = override ?? (t(meta.i18nKey, meta.defaultLabel) as string);
      let href: string | undefined = current;

      // Resolve dynamic params in a single pass. Substitute EVERY `{{param}}`
      // placeholder in the label (split/join, not `replace`, so a label that
      // references a param more than once — e.g. "Drive {{id}} (#{{id}})" —
      // fully resolves) and replace the `:param` segment in the href with its
      // concrete value.
      for (const [key, value] of Object.entries(params)) {
        if (!value) continue;
        label = label.split(`{{${key}}}`).join(value);
        href = href.replace(`:${key}`, value);
      }

      items.unshift({
        label,
        // The trailing (current) item is plain text — no link.
        href: current === matchedPattern ? undefined : href,
      });

      current = meta.parent;
    }

    return items;
  }, [location.pathname, params, overrides, t]);
}
